/**
 * The outcome evaluator.
 *
 * After a routed model returns, the consumer must turn the real result into an {@link Outcome}: a
 * quality judgment plus the observed latency and cost. Quality can come from anything, an LLM-as-judge,
 * a regex, a classifier, or a human, so this module stays scorer-agnostic and only provides safe
 * constructors that validate the latency and cost are strictly positive (the Exponential likelihood
 * has no mass at zero) and a threshold helper that turns a numeric score into an acceptance.
 *
 * @packageDocumentation
 */

import { BayesRouteError } from '../errors.js';
import type { Outcome } from '../types.js';

export type { Outcome, QualityLabel } from '../types.js';

/** A quality evaluator turns a raw model result into either an acceptance boolean or a numeric score. */
export type QualityEvaluator<TResult> = (result: TResult) => boolean | number;

/** True when the quality flag counts as an acceptable output. */
export function isAccepted(quality: Outcome['quality']): boolean {
  return quality === true || quality === 'accepted';
}

function assertPositive(name: string, value: number): void {
  if (!Number.isFinite(value) || value <= 0) {
    throw new BayesRouteError(
      'ERR_INVALID_INPUT',
      `${name} must be a finite positive number, received ${value}`,
    );
  }
}

/** Build a validated {@link Outcome} from a quality flag and the observed latency and cost. */
export function makeOutcome(quality: boolean, latencyMs: number, cost: number): Outcome {
  assertPositive('latencyMs', latencyMs);
  assertPositive('cost', cost);
  return { quality, latencyMs, cost };
}

/** An accepted outcome with the observed latency and cost. */
export function acceptedOutcome(latencyMs: number, cost: number): Outcome {
  return makeOutcome(true, latencyMs, cost);
}

/** A rejected outcome with the observed latency and cost. */
export function rejectedOutcome(latencyMs: number, cost: number): Outcome {
  return makeOutcome(false, latencyMs, cost);
}

/**
 * Turn a numeric quality score into a validated outcome: accepted when `score >= threshold`. The score
 * and threshold may be on any scale as long as they agree.
 */
export function outcomeFromScore(
  score: number,
  threshold: number,
  latencyMs: number,
  cost: number,
): Outcome {
  if (!Number.isFinite(score) || !Number.isFinite(threshold)) {
    throw new BayesRouteError(
      'ERR_INVALID_INPUT',
      `outcomeFromScore requires finite score and threshold, received score=${score} threshold=${threshold}`,
    );
  }
  return makeOutcome(score >= threshold, latencyMs, cost);
}

/**
 * An async quality evaluator, for an LLM-as-judge or any I/O-bound scorer. The router stays
 * provider-agnostic: you bring the judge call, this is only the type it satisfies.
 */
export type AsyncQualityEvaluator<TResult> = (result: TResult) => Promise<boolean | number>;

/** Normalize an evaluator verdict to a boolean acceptance, accepting scores at or above `threshold`. */
export function evaluate(verdict: boolean | number, threshold = 0.5): boolean {
  return typeof verdict === 'boolean' ? verdict : verdict >= threshold;
}

/** Accept when the string output length is at least `min`, and at most `max` when given. */
export function lengthEvaluator(min: number, max?: number): QualityEvaluator<string> {
  return (result: string) => {
    const { length } = result;
    return length >= min && (max === undefined || length <= max);
  };
}

/** Accept when the string output matches the pattern. */
export function regexEvaluator(pattern: RegExp): QualityEvaluator<string> {
  return (result: string) => pattern.test(result);
}

/** Accept when the string output parses as JSON. */
export function jsonValidEvaluator(): QualityEvaluator<string> {
  return (result: string) => {
    try {
      JSON.parse(result);
      return true;
    } catch {
      return false;
    }
  };
}

/** Combine evaluators so the output is accepted only when every evaluator accepts it. */
export function combineAll<TResult>(
  ...evaluators: ReadonlyArray<QualityEvaluator<TResult>>
): QualityEvaluator<TResult> {
  return (result: TResult) => evaluators.every((evaluator) => evaluate(evaluator(result)));
}

/** Combine evaluators so the output is accepted when any evaluator accepts it. */
export function combineAny<TResult>(
  ...evaluators: ReadonlyArray<QualityEvaluator<TResult>>
): QualityEvaluator<TResult> {
  return (result: TResult) => evaluators.some((evaluator) => evaluate(evaluator(result)));
}
